/**
 * Background music generated by popost.ai for a video (`popost video music make`; off by default, musicEnabled): a track described in words (genre,
 * mood, tempo, instruments), as long as the video, written as an MP3 into the project and used as the fill's "sound".
 * It costs credits by its length and is paid as speech is: priced first (free), made only with --confirm
 * --max-credits N, within what is left of N (wallet.ts).
 *
 * One order (the project, the prompt, the seconds, with or without vocals) is one operation key, so the same command
 * again never pays twice: the platform answers the job it already has. A receipt beside the track (<out>.music.json)
 * keeps the order, the job and the hash of the file: with it the same command reads the file that is there, or
 * downloads the paid track again (reading a job is free), without a price to agree. A changed prompt, length or
 * --vocals is another order, priced and agreed like a new one.
 *
 * A job that failed was refunded and is final for its key (the platform answers the same key with the same failure
 * and never makes it again), so the receipt remembers every failure, of a job or of the request, and the next run of
 * the same order takes the key after it: the same command again really tries again. A key is kept only while its job
 * runs or is ready. A track that takes long answers `running`: the job is read every 3 s, for at most 15 min.
 */
import { sha256 } from '../../core/util';
import { checkUrl, readCapped } from '../../providers/api';
import { AmbiguousSubmitError, PopostApiError } from '../../providers/errors';
import { projectTask } from '../../providers/task';
import { sleep } from '../../providers/time';
import type { Runtime } from '../../runtime';
import { connected, operationKeyOf, quoteMusic, readMusic, startMusic, type Music } from '../hosted-api';
import { POLL_MS, waitAfter } from '../speech/hosted';
import { ToolError } from '../tool';
import type { PriceItem, Wallet } from '../wallet';

/**
 * Generated music is off unless the user switches it on (POPOST_VIDEO_MUSIC=on) and an account is connected: by default
 * a video's sound is its voice-over, the user's own file, or the sound its clips came with.
 */
export const MUSIC_SWITCH = 'POPOST_VIDEO_MUSIC';
export const musicEnabled = (rt: Runtime): boolean => /^(1|on|true|yes)$/i.test((rt.env[MUSIC_SWITCH] ?? '').trim()) && connected(rt);

/** What the platform makes: a track of 3 to 300 s from a prompt of at most 2000 characters. */
export const MIN_SECONDS = 3;
export const MAX_SECONDS = 300;
export const PROMPT_MAX = 2000;
const MAX_BYTES = 64 * 1024 * 1024;
const WAIT_LIMIT_MS = 15 * 60_000;
const PROGRESS_MS = 30_000;

/** The length to ask for: the video's, rounded up to a whole second, within what the platform makes. */
export const musicSeconds = (seconds: number): number => Math.min(MAX_SECONDS, Math.max(MIN_SECONDS, Math.ceil(seconds - 1e-6)));

export interface MusicOrder {
  prompt: string;
  /** Whole seconds, MIN_SECONDS to MAX_SECONDS (musicSeconds). */
  seconds: number;
  /** With sung or spoken voices; default instrumental, which is what lies under a voice-over. */
  vocals: boolean;
  /** The MP3 to write, an absolute path. */
  out: string;
}

interface Receipt {
  version: 1;
  tool: 'popost-hosted-music';
  prompt: string;
  seconds: number;
  vocals: boolean;
  /** The key of the order; a job is asked for under it, or under the key after the last failed job. */
  operationKey: string;
  /** The job that was paid for, once the platform has answered it. */
  id?: string;
  chargedCredits?: number;
  audioSha256?: string;
  /** Jobs of this order that failed (each refunded), in order. */
  failed: string[];
}

/** The prompt was refused: it has to be written again, without names. */
export class MusicRejected extends Error {
  override name = 'MusicRejected';
  constructor(readonly suggestion: string | null) {
    super('popost.ai refused this description of the music; nothing was charged.');
  }
}

export const UNAVAILABLE = 'popost.ai could not make the music (its generator is not available now); nothing was charged. Run the same command again later.';
const HINT = 'Run the same command again: the same description and length reuse the same music job.';

const receiptFile = (out: string): string => out + '.music.json';
const clip = (text: string): string => (text.length > 60 ? text.slice(0, 59) + '…' : text);

/** What the order belongs to: the project's task (the same in every copy of the project), else the file it writes. */
const scopeOf = async (rt: Runtime, out: string): Promise<string> =>
  (rt.project ? (await projectTask(rt, rt.project, true).catch(() => undefined))?.id : undefined) ?? out;

const orderKey = async (rt: Runtime, o: MusicOrder): Promise<string> =>
  operationKeyOf({ music: await scopeOf(rt, o.out), prompt: o.prompt, seconds: o.seconds, vocals: o.vocals });

/** The receipt beside the track when it is this order's; a new one otherwise. */
const receiptOf = async (rt: Runtime, o: MusicOrder): Promise<Receipt> => {
  const operationKey = await orderKey(rt, o);
  const fresh: Receipt = { version: 1, tool: 'popost-hosted-music', prompt: o.prompt, seconds: o.seconds, vocals: o.vocals, operationKey, failed: [] };
  try {
    const kept = JSON.parse(await rt.fs.readText(receiptFile(o.out))) as Partial<Receipt> | null;
    if (!kept || kept.operationKey !== operationKey) return fresh;
    return { ...fresh, ...(typeof kept.id === 'string' ? { id: kept.id } : {}), ...(typeof kept.chargedCredits === 'number' ? { chargedCredits: kept.chargedCredits } : {}), ...(typeof kept.audioSha256 === 'string' ? { audioSha256: kept.audioSha256 } : {}), failed: Array.isArray(kept.failed) ? kept.failed.filter((f): f is string => typeof f === 'string') : [] };
  } catch {
    return fresh;
  }
};

const keep = async (rt: Runtime, out: string, receipt: Receipt): Promise<void> => {
  await rt.fs.mkdir(rt.path.dirname(out));
  await rt.fs.writeFile(receiptFile(out), JSON.stringify(receipt, null, 2) + '\n');
};

/** The key a new job of this order is asked for under: the order's, or the one after its last failed job. */
const nextKey = (r: Receipt): string => {
  const last = r.failed[r.failed.length - 1];
  return last === undefined ? r.operationKey : operationKeyOf({ music: r.operationKey, after: last });
};

/** The track of the receipt is in the file, as it was downloaded. */
const inPlace = async (rt: Runtime, out: string, r: Receipt): Promise<boolean> =>
  r.audioSha256 !== undefined && (await rt.fs.readFile(out).then((bytes) => sha256(bytes) === r.audioSha256, () => false));

/** What this order costs (a free quote), as a line of the command's price; nothing when its track was paid for already. */
export const musicPrice = async (rt: Runtime, o: MusicOrder): Promise<PriceItem[]> => {
  if ((await receiptOf(rt, o)).id) return [];
  return [{ kind: 'music', what: (o.vocals ? 'music with vocals: ' : 'instrumental music: ') + clip(o.prompt), credits: await quoteMusic(rt, o.seconds), seconds: o.seconds }];
};

const download = async (rt: Runtime, url: string, out: string): Promise<string> => {
  const response = await rt.fetch(checkUrl(url, 'music audio'));
  if (!response.ok) throw new ToolError('The music could not be downloaded (HTTP ' + response.status + '). Run the same command again: the track is paid for and is not charged again.');
  const bytes = await readCapped(response, MAX_BYTES);
  // An MP3 starts with an ID3 tag or with a frame (eleven set bits).
  const id3 = bytes[0] === 0x49 && bytes[1] === 0x44 && bytes[2] === 0x33;
  if (bytes.length < 128 || !(id3 || (bytes[0] === 0xff && ((bytes[1] ?? 0) & 0xe0) === 0xe0))) throw new ToolError('popost.ai did not return an MP3 for the music. Run the same command again: the track is paid for and is not charged again.');
  await rt.fs.mkdir(rt.path.dirname(out));
  await rt.fs.writeFile(out, bytes);
  return sha256(bytes);
};

/** Reads a running job every 3 s until it is ready or failed, for at most 15 min; a line on stderr every 30 s. */
const untilDone = async (rt: Runtime, job: Music): Promise<Music> => {
  const started = rt.now().getTime();
  let last = job, said = started, failures = 0, pause = POLL_MS;
  while (last.state === 'running') {
    const now = rt.now().getTime();
    if (now - started >= WAIT_LIMIT_MS) throw new ToolError('popost.ai is still making the music after 15 min; run the same command again later: it waits for the same job, without a new charge.');
    if (now - said >= PROGRESS_MS) {
      rt.stderr('popost.ai is making ' + job.seconds + ' s of music (' + Math.round((now - started) / 1000) + ' s so far)\n');
      said = now;
    }
    await sleep(rt, pause);
    try {
      last = await readMusic(rt, job.id);
      failures = 0;
      pause = POLL_MS;
    } catch (e) {
      if (!(e instanceof PopostApiError && e.code === 'RATE_LIMITED')) failures += 1;
      const wait = waitAfter(e, failures);
      if (wait === undefined) throw e;
      pause = wait;
    }
  }
  return last;
};

/** A job that failed, or a refusal of the request: remembered (the next run takes a new key), then reported. */
const failed = async (rt: Runtime, out: string, r: Receipt, what: { id: string; failure: string | null; suggestion: string | null }): Promise<never> => {
  await keep(rt, out, { version: 1, tool: r.tool, prompt: r.prompt, seconds: r.seconds, vocals: r.vocals, operationKey: r.operationKey, failed: [...r.failed, what.id] });
  if (what.failure === 'rejected') throw new MusicRejected(what.suggestion);
  throw new ToolError(UNAVAILABLE);
};

const asked = async (rt: Runtime, o: MusicOrder, r: Receipt, maxCredits: number): Promise<Music> => {
  const operationKey = nextKey(r);
  try {
    return await startMusic(rt, { operationKey, prompt: o.prompt, seconds: o.seconds, instrumental: !o.vocals, maxCredits }, HINT);
  } catch (e) {
    if (e instanceof AmbiguousSubmitError) throw new ToolError(e.message);
    const suggestion = e instanceof PopostApiError && typeof e.details.suggestion === 'string' && e.details.suggestion ? e.details.suggestion : null;
    if (e instanceof PopostApiError && e.code === 'CONTENT_REJECTED') return failed(rt, o.out, r, { id: 'refused:' + operationKey, failure: 'rejected', suggestion });
    if (e instanceof PopostApiError && e.code === 'UPSTREAM_ERROR') return failed(rt, o.out, r, { id: 'refused:' + operationKey, failure: 'unavailable', suggestion: null });
    throw e;
  }
};

export interface MadeMusic { seconds: number; chargedCredits: number; /** The track was paid for by an earlier run. */ kept?: true }

/**
 * The track of this order in o.out. Paid for before: the file that is there, or the same track downloaded again, for
 * nothing. Otherwise it is quoted, held against what is left in `wallet`, made, waited for and downloaded.
 */
export const makeMusic = async (rt: Runtime, o: MusicOrder, wallet: Wallet): Promise<MadeMusic> => {
  let receipt = await receiptOf(rt, o);
  const paidBefore = receipt.id !== undefined;
  if (paidBefore && (await inPlace(rt, o.out, receipt))) return { seconds: o.seconds, chargedCredits: 0, kept: true };
  let job: Music;
  if (receipt.id !== undefined) job = await readMusic(rt, receipt.id);
  else {
    wallet.check(await quoteMusic(rt, o.seconds), 'Making ' + o.seconds + ' s of music with popost.ai');
    job = await asked(rt, o, receipt, wallet.left);
    if (job.state !== 'failed') {
      receipt = { ...receipt, id: job.id };
      await keep(rt, o.out, receipt);
    }
  }
  job = await untilDone(rt, job);
  if (job.state === 'failed') return failed(rt, o.out, receipt, job);
  if (job.state !== 'ready' || !job.audioUrl) throw new ToolError('The popost.ai music is ' + (job.state || 'not ready') + '; run the same command again.');
  const audioSha256 = await download(rt, job.audioUrl, o.out);
  await keep(rt, o.out, { ...receipt, id: job.id, chargedCredits: job.chargedCredits, audioSha256 });
  if (paidBefore) return { seconds: job.seconds || o.seconds, chargedCredits: 0, kept: true };
  wallet.pay(job.chargedCredits);
  return { seconds: job.seconds || o.seconds, chargedCredits: job.chargedCredits };
};
